/* ========== ACTIONS ========== */
function startApp() { state.view = 'home'; render(); }
function showHome() { state.view = 'home'; render(); }
function showLibrary() { state.view = 'library'; render(); }
function showSearch() { state.view = 'search'; render(); }
function showSettings() { state.view = 'settings'; render(); }
function showWelcome() { state.view = 'welcome'; render(); }
function openNote(id) { console.log('Open note:', id); }
function playNote(id) { console.log('Play note:', id); }

function startRecording() {
  state.view = 'recording';
  state.recording = true;
  state.recordingTime = 0;
  state.transcription = '';
  render();

  // Request microphone permission and start recording
  if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
      state.mediaRecorder = new MediaRecorder(stream, { mimeType: 'audio/webm' });
      state.audioChunks = [];
      state.mediaRecorder.ondataavailable = e => { if (e.data.size) state.audioChunks.push(e.data); };
      state.mediaRecorder.start(1000);

      // Update timer
      state.timerInterval = setInterval(() => {
        state.recordingTime++;
        if (state.recordingTime >= 600) saveRecording(); // 10 min max
        render();
      }, 1000);
    }).catch(() => {
      state.transcription = 'Microphone access denied. Please allow microphone access to record.';
      render();
    });
  }
}

function cancelRecording() {
  if (state.mediaRecorder && state.mediaRecorder.state === 'recording') {
    state.mediaRecorder.stop();
    state.mediaRecorder.stream.getTracks().forEach(t => t.stop());
  }
  if (state.timerInterval) clearInterval(state.timerInterval);
  state.recording = false;
  state.view = 'home';
  render();
}

async function saveRecording() {
  if (state.mediaRecorder && state.mediaRecorder.state === 'recording') {
    state.mediaRecorder.stop();
    state.mediaRecorder.stream.getTracks().forEach(t => t.stop());
  }
  if (state.timerInterval) clearInterval(state.timerInterval);
  state.recording = false;

  // Gather audio blobs into a single blob
  const audioBlob = new Blob(state.audioChunks, { type: 'audio/webm' });
  const audioKey = 'audio/' + Date.now() + '.webm';
  const durationMinutes = (state.recordingTime / 60).toFixed(1);

  // Convert to base64 for upload
  const reader = new FileReader();
  reader.readAsDataURL(audioBlob);

  reader.onloadend = async () => {
    const base64Data = reader.result.split(',')[1];

    try {
      // 1. Try to upload audio
      let uploadSuccess = false;
      let audioUrl = '';
      try {
        const uploadRes = await api.uploadAudio({ audioBase64: base64Data, key: audioKey });
        uploadSuccess = true;
        audioUrl = uploadRes.url || '';
      } catch (e) {
        console.log('Audio upload failed:', e.message);
      }

      // 2. Try to get transcription from Deepgram
      let transcription = '';
      try {
        const transcribeRes = await api.transcribe({ audioBase64: base64Data });
        transcription = transcribeRes.transcript || '';
      } catch (e) {
        console.log('Transcription failed:', e.message);
        transcription = `Voice recording (${durationMinutes} min)`;
      }

      // 3. Get summary if transcription exists
      let summary = '';
      if (transcription && transcription.length > 30) {
        try {
          const summaryRes = await api.summarize({ text: transcription });
          summary = summaryRes.summary || '';
        } catch (e) { 
          console.log('Summarize failed:', e);
        }
      }

      // 4. Create the note with available data
      const title = transcription.toLowerCase().includes('voice recording') ? 
        `Voice Note (${durationMinutes} min)` : 
        (transcription.split('.')[0].slice(0, 60) || `Voice Note (${durationMinutes} min)`);
      const content = summary || transcription;

      const noteSuccess = await api.createNote({
        title: title,
        content: content,
        hasAudio: uploadSuccess,
        audioKey: uploadSuccess ? audioKey : null,
        duration: state.recordingTime
      });

      state.notes.unshift(noteSuccess);
      state.transcription = '';
      state.audioChunks = [];
      state.view = 'home';
      render();

      // Show different success messages based on what worked
      if (!uploadSuccess || !transcription) {
        console.log('Saved note with fallback data. API may need configuration.');
      }

    } catch (e) {
      console.error('Save completely failed:', e);
      // Fallback: create a minimal note without API calls
      try {
        const fallbackNote = await api.createNote({
          title: `Voice Note (${durationMinutes} min)`,
          content: 'Voice recording saved',
          hasAudio: false,
          audioKey: null,
          duration: state.recordingTime
        });
        state.notes.unshift(fallbackNote);
      } catch (fallbackError) {
        console.error('Even fallback failed:', fallbackError);
      }

      state.transcription = '';
      state.audioChunks = [];
      state.view = 'home';
      render();
    }
  };
}

/* ========== RENDER ========== */
function render() {
  const views = {
    welcome: renderWelcome,
    home: renderHome,
    library: renderLibrary,
    recording: renderRecording,
    search: renderSearch,
    settings: renderSettings
  };
  app.innerHTML = (views[state.view] || views.welcome)();
}

/* ========== INIT ========== */
function init() {
  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  const meta = document.querySelector('meta[name="viewport"]') || document.createElement('meta');
  meta.name = 'viewport';
  meta.content = 'width=device-width, initial-scale=1, viewport-fit=cover';
  if (!meta.parentNode) document.head.appendChild(meta);

  const font = document.createElement('link');
  font.rel = 'stylesheet';
  font.href = 'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Source+Serif+Pro:wght@400;600&display=swap';
  document.head.appendChild(font);

  loadNotes();
}

async function loadNotes() {
  try {
    const notes = await api.listNotes();
    state.notes = notes || [];
    render();
  } catch(e) { 
    console.log('Could not load notes, using empty list');
    state.notes = [];
    render(); 
  }
}

